/*\n  # Update Pending Invites View for Manual Invites\n\n  ## Summary\n  Updates the pending_invites_with_details view to display user-friendly defaults\n  when manual invites don't have an associated project.\n\n  ## Changes\n  - Show "(Manual Invite)" when project_name is null\n  - Show "(No Project)" when project_number is null\n  - Show current date when substantial_completion_date is null\n\n  ## Notes\n  This makes the view more useful for manual invites created without projects.\n*/\n\nCREATE OR REPLACE VIEW pending_invites_with_details AS\nSELECT \n  pi.id,\n  pi.contact_id,\n  pi.project_id,\n  pi.status,\n  pi.created_at,\n  pi.reviewed_by,\n  pi.reviewed_at,\n  pi.invite_sent_at,\n  pi.decline_reason,\n  pi.notes,\n  c.full_name as contact_name,\n  c.email as contact_email,\n  c.phone as contact_phone,\n  COALESCE(p.name, '(Manual Invite)') as project_name,\n  COALESCE(p.project_number, '(No Project)') as project_number,\n  COALESCE(p.substantial_completion_date, CURRENT_DATE) as substantial_completion_date,\n  EXTRACT(DAY FROM (now() - pi.created_at)) as days_pending,\n  reviewer.full_name as reviewed_by_name\nFROM pending_punchlist_invites pi\nINNER JOIN contacts c ON c.id = pi.contact_id\nLEFT JOIN projects p ON p.id = pi.project_id\nLEFT JOIN profiles reviewer ON reviewer.id = pi.reviewed_by

\n
